    /**
     * Tests getting all BackgroundChecks.
     *
     * @return    Collection
     */
    public List<BackgroundCheck> testGetAll() throws Throwable {
    LOGGER.info( "BackgroundCheckTest:testGetAll() - Retrieving Collection of BackgroundChecks:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all BackgroundCheck : " );
    List<BackgroundCheck> collection  = null;

    try {
        // call the static get method on the BackgroundCheckService
        collection = service.getAllBackgroundCheck();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            BackgroundCheck currEntity  = null;
            Iterator<BackgroundCheck> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getBackgroundCheckId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

